def clean(df):
    df = df.drop_duplicates().copy()
    m = df['body_mass_g'].astype(str).str.replace(',', '', regex=False).str.strip()
    m = pd.to_numeric(m, errors='coerce')
    m = m.where((m >= 2500) & (m <= 6500))
    df['body_mass_g'] = m
    return df

def answer(df):
    g = df.dropna(subset=['sex', 'body_mass_g']).groupby('sex')['body_mass_g'].mean()
    return {str(k): float(v) for k, v in g.items()}
